use std::borrow::Borrow;
struct S<'a> { key: &'a [u8], pos: usize }
impl<'a> S<'a> {
    fn f<'b, Data>(&'b mut self, data: Data) -> impl Iterator<Item = u8> + 'b
    where
        Data: IntoIterator,
        Data::Item: Borrow<u8>,
        Data::IntoIter: 'b,
    {
        let key = self.key;
        let pos = &mut self.pos;
        data.into_iter()
            .map(|item| *item.borrow())
            .map(move |byte| {
                let key_byte = key[*pos % key.len()];
                *pos += 1;
                byte ^ key_byte
            })
    }
}
fn main() {
    let key = [1u8, 2, 3];
    let mut s = S { key: &key, pos: 0 };
    let v: Vec<u8> = s.f([10u8, 20, 30, 40]).collect();
    println!("{:?}", v);
    let v2: Vec<u8> = s.f(&[10u8, 20]).collect();
    println!("{:?}", v2);
}
EOF
